namespace {bool watch=false;uint64_t allocations=0;void check(bool p,const char*m){if(!p)throw std::runtime_error(m);}class Original:public H8SEmulator{public:void histories(int r,int w){lastread=r;lastwrite=w;}};
struct Event{uint64_t clocks;unsigned at;uint8_t value;bool write;};
template<class D>struct Tape{D&d;bool overlay=false,recording=false,context=false,trampoline=false;unsigned count=0,lcdBusy=2,phasePc=0,command=0,remaining=0,pageWrites=0,page=0,dropIndex=~0u,stallReads=0,lastReads=0;uint32_t tick=0;bool inject=false,injected=false;std::array<Event,16>events{};explicit Tape(D&s):d(s){}void record(unsigned a,uint8_t v,bool w){if(!recording||!w&&a>=phasePc&&a<phasePc+12||context&&a>=0xfffea0&&a<0xffff10||trampoline&&!w&&a>=0xfffd10&&a<0xfffd1c)return;check(count<events.size(),"Tape overflow");events[count++]={d.cycles,a,v,w};}uint8_t read(unsigned a){auto v=d.memory[a<0x10000&&overlay?0x400000+a:a];if(a==0x600004)v=uint8_t(7|((d.memory[0x600000]&8)?16:0));if(a>=0xfffd20&&a<=0xfffd23){if(a==0xfffd20)tick=uint32_t(d.cycles/1000);v=uint8_t(tick>>((0xfffd23-a)*8));}if(pageWrites==256&&a==page+255&&lastReads++<stallReads)v^=1;if(a==0xffffc7)v=lcdBusy?(--lcdBusy,0x80):0;record(a,v,false);return v;}void write(unsigned a,uint8_t v){record(a,v,true);if(a>=0x200000&&a<0x240000){unsigned off=a-0x200000;if(command==3){if(!pageWrites)page=a;if(pageWrites!=dropIndex)d.memory[a]=v;++pageWrites;if(inject&&!injected&&pageWrites==128){if constexpr(std::is_same_v<D,Original>)d.pending_irqs=uint64_t(1)<<38;else d.pendingIrqs=uint64_t(1)<<38;injected=true;}if(!--remaining)command=0;return;}if(command==0&&off==0x5555&&v==0xaa)command=1;else if(command==1&&off==0x2aaa&&v==0x55)command=2;else if(command==2&&off==0x5555&&v==0xa0){command=3;remaining=256;pageWrites=0;}else command=0;return;}d.memory[a]=v;if(a==0xffffcf)overlay=!(v&1);}};
struct OldBus:H8SDevice{Tape<Original>&t;explicit OldBus(Tape<Original>&s):t(s){}uint8_t read(unsigned a)override{return t.read(a);}void write(unsigned a,uint8_t v)override{t.write(a,v);}};
struct NewBus:kstation::ControllerResourceBus{Tape<kstation::ControllerDeviceState>&t;explicit NewBus(Tape<kstation::ControllerDeviceState>&s):t(s){}bool mapped(unsigned a)const override{return a<0x10000||a>=0x200000&&a<0x240000||a>=0x400000&&a<0x420000||a>=0x600000&&a<0x600010||a>=0xfffd00;}uint8_t read(unsigned a)override{return t.read(a);}void write(unsigned a,uint8_t v)override{t.write(a,v);}};
struct Fixture{using R=kstation::ControllerProgramStateRuntime;std::unique_ptr<Original>a=std::make_unique<Original>();std::unique_ptr<kstation::ControllerDeviceState>d=std::make_unique<kstation::ControllerDeviceState>();Tape<Original>x{*a};Tape<kstation::ControllerDeviceState>y{*d};OldBus xb{x};NewBus yb{y};R native;kstation::ControllerDspTransferRuntime dsp;kstation::ControllerPanelHardwareRuntime panel;kstation::ControllerPanelRefreshRuntime refresh;kstation::ControllerProgramVoiceInitRuntime init;kstation::ControllerProgramVoicesRuntime voices;kstation::ControllerInterruptRuntime irq;uint64_t phases=0,io=0,shorts=0,irqPhases=0;void byte(unsigned at,unsigned v){a->memory[at]=d->memory[at]=uint8_t(v);}void word(unsigned at,unsigned v){byte(at,v>>8);byte(at+1,v);}void wide(unsigned at,unsigned v){word(at,v>>16);word(at+2,v);}
R::Services services(){return {dsp,panel,refresh,init,voices};}
Fixture(const std::vector<uint8_t>&rom,unsigned entry,unsigned flags,unsigned mode){a->loadmem(rom.data(),rom.size(),0);d->loadMemory(rom.data(),rom.size(),0);for(unsigned i=0;i<rom.size();++i)byte(0x400000+i,rom[i]);for(auto p:{std::pair{0,0x10000},std::pair{0x200000,0x40000},std::pair{0x400000,0x20000},std::pair{0x600000,16},std::pair{0xfffd00,0x300}})a->memmap(&xb,p.first,p.second);d->attachBus(&yb);check(irq.bindVerifiedFirmware(*d,rom.data(),rom.size()),"IRQ bind");irq.setMask(flags&128?kstation::ControllerInterruptRuntime::Mask::Disabled:kstation::ControllerInterruptRuntime::Mask::Enabled);check(native.bindVerifiedFirmware(*d,rom.data(),rom.size()),"Program bind");check(dsp.bindVerifiedFirmware(*d,rom.data(),rom.size()),"DSP bind");check(panel.bindBootResources(*d,rom.data(),rom.size())&&panel.bindMirroredFirmware(*d,rom.data(),rom.size()),"Panel bind");check(refresh.bindVerifiedFirmware(*d,rom.data(),rom.size()),"Refresh bind");check(init.bindVerifiedFirmware(*d,rom.data(),rom.size()),"Init bind");check(voices.bindVerifiedFirmware(*d,rom.data(),rom.size()),"Voices bind");for(unsigned i=0;i<0x2000;++i)byte(0xba00+i,0);for(unsigned i=0;i<128;++i)byte(0x239000+i,(i*13+flags)&255);for(unsigned i=0;i<4;++i){byte(0xd030+i*18+9,i+1);wide(0xd030+i*18,0xcf00);}byte(0xcd82,2);byte(0xcd83,3);byte(0xcd77,mode);byte(0xcc02,flags);byte(0xbb23,flags);byte(0xd022,4);byte(0xd02c,0);byte(0xcd6a,0);byte(0xcd6b,0);byte(0x60000a,0x12);byte(0x60000c,0x34);byte(0x60000e,0x56);word(0xc598,0xffff);wide(0xfffe50,0xdeadbeef^flags);a->pc=a->makepc(entry);a->setSP(0xffff00);wide(0xffff00,0x3ae8);a->ccr=uint8_t(flags);a->histories(-1,-1);a->cycles=d->cycles=flags==255?~uint64_t(0)-7:100000;a->pending_irqs=d->pendingIrqs=flags==255?uint64_t(1)<<38:0;a->reg32(0)=0x239000;check(native.start(entry==0x4ca0?R::Kind::Load:entry==0x4ce4?R::Kind::Copy:entry==0x4cb8?R::Kind::Address:entry==0x4c36?R::Kind::Index:entry==0x563a?R::Kind::MirrorClear:entry==0x8218?R::Kind::ModeLatch:R::Kind::DspReset,0x239000),"Program start");x.recording=y.recording=true;}

void equal(unsigned pc){if(a->cycles!=d->cycles){std::fprintf(stderr,"PC%x clocks%llu/%llu\n",pc,a->cycles,d->cycles);throw std::runtime_error("Phase clocks");}if(x.count!=y.count){std::fprintf(stderr,"PC%x count%u/%u\n",pc,x.count,y.count);throw std::runtime_error("IO count");}for(unsigned i=0;i<x.count;++i){auto&p=x.events[i];auto&q=y.events[i];if(!(p.clocks==q.clocks&&p.at==q.at&&p.value==q.value&&p.write==q.write)){std::fprintf(stderr,"PC%x IO%u addr%x/%x value%x/%x time%llu/%llu\n",pc,i,p.at,q.at,p.value,q.value,p.clocks,q.clocks);throw std::runtime_error("Ordered IO");}}io+=x.count;}
void run(){for(unsigned i=0;native.active()&&i<12000000;++i){auto pc=unsigned(a->getPC());x.phasePc=y.phasePc=pc&0xffffff;x.context=y.context=true;x.count=y.count=0;check(native.routeServices(*d,services()),"Program route");auto n=native.nextClocks(*d,irq,services());if(i<80||i%1009==0){auto snapshot=native;auto cycle=d->cycles;int read=d->lastRead,write=d->lastWrite;for(unsigned b=0;b<n;++b){auto r=native.advanceBefore(*d,irq,services(),b).clocks;check(!r,"Short accepted");check(!std::memcmp(&snapshot,&native,sizeof(native))&&cycle==d->cycles&&read==d->lastRead&&write==d->lastWrite&&!x.count&&!y.count,"Short mutated");++shorts;}}auto ncl=native.advanceBefore(*d,irq,services(),n).clocks;check(ncl,"Metadata refused");a->step();equal(pc);check((a->ccr&128?kstation::ControllerInterruptRuntime::Mask::Disabled:kstation::ControllerInterruptRuntime::Mask::Enabled)==irq.mask(),"Mask differs");++phases;}check(!native.active()&&a->getPC()==0x3ae8,"Metadata runaway");for(auto p:{std::pair{0x200000,0x40000},std::pair{0xba00,0x2000},std::pair{0xfffd10,0x190},std::pair{0xffff10,0xf0}})check(!std::memcmp(a->memory+p.first,d->memory+p.first,p.second),"Device memory differs");}

};}
void*operator new(size_t n){if(watch)++allocations;if(auto*p=std::malloc(n))return p;throw std::bad_alloc();}void operator delete(void*p)noexcept{std::free(p);}void operator delete(void*p,size_t)noexcept{std::free(p);}
int main(int argc,char**argv){try{if(argc<2)return 77;std::ifstream in(argv[1],std::ios::binary);std::vector<uint8_t>rom{std::istreambuf_iterator<char>(in),{}};uint64_t phases=0,io=0,shorts=0;unsigned cases=0;auto run=[&](unsigned entry,unsigned flags,unsigned mode){Fixture f(rom,entry,flags,mode);watch=true;f.run();watch=false;phases+=f.phases;io+=f.io;shorts+=f.shorts;++cases;};for(unsigned entry:{0x4ca0u,0x4ce4u,0x4cb8u,0x4c36u,0x563au,0x833au,0x8218u})for(unsigned flags=0;flags<256;++flags)for(unsigned mode:{0u,1u,255u})run(entry,flags,mode);{Fixture f(rom,0x4c36,255,0);f.native.reset();auto saved=f.native;auto cycle=f.d->cycles;for(unsigned source:{0xfffea0u,0x1ffffe9fu})check(!f.native.start(Fixture::R::Kind::Index,source),"Index context admitted");check(!f.native.start(static_cast<Fixture::R::Kind>(255)),"Invalid kind admitted");check(!f.native.start(Fixture::R::Kind::Copy,0xfffe90),"Copy context admitted");check(!std::memcmp(&saved,&f.native,sizeof(saved))&&cycle==f.d->cycles&&!f.y.count,"Invalid admission mutated");for(auto r:Fixture::R::CodeRanges)for(unsigned at:{r.begin,r.end-1})for(unsigned alias:{0u,0x400000u,0x1000000u,0x1400000u}){bool threw=false;try{f.d->write8(at+alias,0);}catch(const std::logic_error&){threw=true;}check(threw&&cycle==f.d->cycles&&!f.y.count,"Program immutable guard");}}
check(!allocations,"Processing allocation");std::printf("{\"passed\":true,\"graphs\":%u,\"native_phases\":%llu,\"ordered_io\":%llu,\"short_budgets\":%llu,\"processing_allocations\":%llu}\n",cases,phases,io,shorts,allocations);return 0;}catch(const std::exception&e){std::fprintf(stderr,"FAIL:%s\n",e.what());return 1;}}
